def drive_inputs() -> dict:
    # Large contents are named by a label and rebuilt by the test, so the vectors stay small.
    large = {
        "a*1048577": "a" * (1024 * 1024 + 1),
        "ż*524289": "ż" * (512 * 1024 + 1),
        "ż*524288": "ż" * (512 * 1024),
    }
    creates = [
        {"folder_id": "docs", "name": "x", "content": "a"},
        {"folder_id": "docs", "name": "x", "content": "a*1048577"},
        {"folder_id": "docs", "name": "x", "content": "ż*524289"},
        {"folder_id": "docs", "name": "x", "content": "ż*524288"},
        {"folder_id": "docs", "name": "bad\nname", "content": "a"},
        {"folder_id": "../docs", "name": "x", "content": "a"},
        {"folder_id": "docs", "name": "", "content": "a"},
        {"folder_id": "docs", "name": "x", "content": ""},
        {"folder_id": "docs", "name": "x", "content": "  padded  "},
        {"folder_id": "docs", "name": "x", "content": "a", "as_document": "yes"},
        {"folder_id": "root", "name": "x" * 201, "content": "a"},
    ]
    found = {}
    for data in creates:
        real = {**data, "content": large.get(data["content"], data["content"])}
        result = validated(drive.CreateFile, real)
        if "ok" in result and data["content"] in large:
            result["ok"]["content"] = data["content"]
        found[json.dumps(data, sort_keys=True)] = {"input": data, **result}
    others = {
        "list_folder": [{"folder_id": "root"}, {"folder_id": "x", "limit": 101}, {"folder_id": "x", "cursor": "c" * 1001}],
        "search_files": [{"text": "a\tb"}, {"text": "it's"}, {"text": ""}, {"text": "x", "limit": 51}],
        "read_file": [{"file_id": "a"}, {"file_id": "a", "max_chars": 0}, {"file_id": "a", "max_chars": 100_001}],
    }
    models = {"list_folder": drive.ListFolder, "search_files": drive.SearchFiles, "read_file": drive.ReadFile}
    rest = {
        name: {json.dumps(data, sort_keys=True): {"input": data, **validated(models[name], data)} for data in cases}
        for name, cases in others.items()
    }
    quoted = {text: drive.quoted(text) for text in ["it's", "a\\' or name contains '", "plain", "\\\\", "''"]}
    return {"create_file": dict(found), **rest, "quoted": quoted}


