CORE_CODECS = ["utf-8", "ascii", "latin-1", "cp1252", "utf-8-sig", "utf-16", "utf-16-le", "utf-16-be", "utf-32",
               "utf-32-le", "utf-32-be", "koi8-r", "cp037", "iso-8859-8", "tis-620", "undefined", "charmap", "cp1255"]


def codec_cases() -> dict:
    samples = [b"", b"plain text", b"caf\xc3\xa9", b"caf\xe9", b"\xff\xfe", b"\xef\xbb\xbfhi", b"\xc3\x28",
               b"\xe2\x82\xac", b"\xf0\x9f\x98\x80", b"\xed\xa0\x80", b"\xf0\x80\x80", b"\xe2\x82", b"a\x80b",
               b"\xfe\xff\x00a", b"\xff\xfea\x00", b"a\x00", b"\x00a\x00", b"\xd8\x00", b"\x00\xd8", b"\x00\xdc\x00\x00",
               b"\x00\x00\xfe\xff\x00\x00\x00a", b"\xff\xfe\x00\x00a\x00\x00\x00", b"a\x00\x00\x00b",
               bytes(range(256)), bytes(range(128, 256))]
    for _ in range(CODEC_RANDOM):
        samples.append(bytes(RANDOM.randrange(256) for _ in range(RANDOM.randint(1, 9))))
    found = []
    calls = [(name, data) for name in CODEC_NAMES for data in (b"caf\xe9", b"caf\xc3\xa9")]
    calls += [(name, data) for name in CORE_CODECS for data in samples]
    for name, data in calls:
        results = {}  # one record per codec and bytes, with the answer of each error handler
        for errors in ("strict", "replace", "surrogateescape"):
            try:
                results[errors] = {"ok": data.decode(name, errors)}
            except BaseException as error:  # noqa: BLE001
                results[errors] = {"error": raised(error)}
        found.append({"name": name, "data": data.hex(), **results})
    encodes = []
    for name in ["iso-2022-jp", "us-ascii", "utf-8", "latin-1", "raw-unicode-escape"]:
        for text in ["plain", "café", "日本", "ｶ", "\U0001f600", "\udc80"]:
            try:
                result = {"ok": text.encode(name).hex()}
            except BaseException as error:  # noqa: BLE001
                result = {"error": raised(error)}
            encodes.append({"name": name, "text": text, **result})
    return {"decode": found, "encode": encodes}


