def address_cases() -> dict:
    def py(function, value):
        try:
            return {"ok": function(value)}
        except OperationError as error:
            return {"code": error.code, "message": error.message}
        except BaseException as error:  # noqa: BLE001
            return {"error": raised(error)}

    parsed = {value: py(addresses.parse, value) for value in ADDRESSES}
    ids = ["ada@example.com", "*@example.com", "*@b.example", "*@kobe.jp", "*@city.kobe.jp", "*@com", "*@co.uk",
           "*@x.co.uk", "Ada@example.com", "*@Example.com", "unsupported", "*@xn--mnchen-3ya.de", "*@münchen.de", "",
           "*@", "ada@example", "*@sub.example.com", "*@github.io", "*@x.github.io"]
    valid = {value: addresses.valid_id(value) for value in [*ADDRESSES, *ids]}
    names = {value: addresses.name(value) for value in ids}
    choices = {value: py(addresses.choices, value) for value in [*ADDRESSES, "example.com", "@example.com", "*@example.com", "kobe.jp", "Example.COM", "", " ", "x"]}
    hosts = ["example.com", "Example.COM.", "localhost", "127.0.0.1", "[::1]", "::1", "0x7f.1", "127.1", "a.b.c.example",
             "x.example", "kobe.jp", "city.kobe.jp", "ck", "www.ck", "x.ck", "münchen.de", "", " ", "x" * 254, "a." * 100 + "com",
             "github.io", "x.github.io", "foo.bar", "co.uk", "x.co.uk", "s3.amazonaws.com", "x.s3.amazonaws.com",
             "x.compute.amazonaws.com", "y.x.compute.amazonaws.com", "blogspot.com", "x.blogspot.com", "Ⅳ.com", "xn--4gq.com"]
    canonical = {host: {"plain": py(sites.canonical_host, host), "reserved": py(lambda h: sites.canonical_host(h, reserved=True), host)} for host in hosts}
    registrable = {host: sites.registrable(host) for host in ["example.com", "a.b.example.com", "kobe.jp", "city.kobe.jp", "x.kobe.jp", "y.x.kobe.jp", "ck", "www.ck", "x.ck", "github.io", "x.github.io", "co.uk", "x.co.uk", "com", "foo.zz", "x.example", "s3.amazonaws.com", "x.compute.amazonaws.com", "y.x.compute.amazonaws.com", "xn--fsqu00a.xn--3lr804guic"]}
    return {"parse": parsed, "valid_id": valid, "name": names, "choices": choices, "canonical_host": canonical, "registrable": registrable}


