def random_header_cases() -> list[dict]:
    """Random encoded-word headers: charsets, encodings, malformed payloads, whitespace and line breaks."""
    # Without the CJK codecs: src/lib/codecs.ts decodes those with the runtime's decoders,
    # which accept some malformed sequences Python refuses (HEADER_TEXTS has well-formed ones).
    charsets = ["utf-8", "UTF-8", "iso-8859-1", "windows-1252", "koi8-r", "us-ascii", "x-nope", "utf-16", "utf-32le", "utf-7",
                "latin-1", "", "cp1251", "utf-8*en", "iso-8859-15", "cp037", "tis-620", "ascii", "utf-8-sig"]
    plain = ["", " ", "  ", "\t", "\r\n ", "Hello", "Grüße", " world ", "(c)", "日本", "a\x00b", "x" * 30, "\n"]
    found = []
    for _ in range(HEADERS_RANDOM):
        parts = []
        for _ in range(RANDOM.randint(1, 5)):
            if RANDOM.random() < 0.65:
                charset = RANDOM.choice(charsets)
                encoding = RANDOM.choice(["q", "Q", "b", "B"])
                raw = bytes(RANDOM.choice([0x41, 0x61, 0x20, 0xC3, 0xA9, 0xE9, 0xFF, 0x80, 0x3D, 0x5F, 0xE2, 0x82, 0xAC, 0x1B, 0x24, 0x42]) for _ in range(RANDOM.randint(0, 8)))
                if encoding in "qQ":
                    payload = "".join(chr(b) if 0x30 <= b < 0x7B and b not in (0x3D, 0x5F) else f"=%02X" % b for b in raw)
                    if RANDOM.random() < 0.15:
                        payload = payload + RANDOM.choice(["=", "=Z", "_", "?"])
                else:
                    payload = base64.b64encode(raw).decode()
                    if RANDOM.random() < 0.25:
                        payload = payload.rstrip("=") if RANDOM.random() < 0.5 else payload + RANDOM.choice(["=", "!", "A", " "])
                parts.append(f"=?{charset}?{encoding}?{payload}?=")
            else:
                parts.append(RANDOM.choice(plain))
        value = RANDOM.choice(["", " ", "\t", "\r\n ", "\n "]).join(parts)
        try:
            result = {"ok": mime.header_text(value)}
        except BaseException as error:  # noqa: BLE001
            result = {"error": raised(error)}
        found.append({"value": value, **result})
    return found


# Tables.


def js_string(text: str) -> str:
    """A TypeScript string literal: printable ASCII as is, everything else as \\u escapes (UTF-16)."""
    out = []
    for char in text:
        point = ord(char)
        if char in '"\\':
            out.append("\\" + char)
        elif 0x20 <= point < 0x7F:
            out.append(char)
        elif point < 0x10000:
            out.append(f"\\u{point:04x}")
        else:
            point -= 0x10000
            out.append(f"\\u{0xD800 + (point >> 10):04x}\\u{0xDC00 + (point & 0x3FF):04x}")
    return '"' + "".join(out) + '"'


def b36(n: int) -> str:
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    out = ""
    while True:
        n, r = divmod(n, 36)
        out = digits[r] + out
        if n == 0:
            return out


def packed(ranges) -> str:
    """Half-open ranges as base-36 gaps and lengths: start - previous end, end - start."""
    parts = []
    last = 0
    for start, end in ranges:
        parts += [b36(start - last), b36(end - start)]
        last = end
    return ",".join(parts)


def runs(points) -> list[tuple[int, int]]:
    found: list[tuple[int, int]] = []
    for point in sorted(points):
        if found and found[-1][1] == point:
            found[-1] = (found[-1][0], point + 1)
        else:
            found.append((point, point + 1))
    return found


def write_zones() -> None:
    names = sorted(zoneinfo.available_timezones())
    lines = [
        HEADER.format(version=VERSION),
        "/** `zoneinfo.available_timezones()`: IANA names, aliases such as US/Pacific included. */",
        "export const ZONES: ReadonlySet<string> = new Set([",
        *(f"\t{js_string(name)}," for name in names),
        "]);",
        "",
    ]
    (CLOUDFLARE / "src/lib/zones.ts").write_text("\n".join(lines))


def check_digits() -> None:
    """src/lib/digits.ts holds Python's `isdigit()`-but-not-`isdecimal()` characters as ranges; fail if they differ."""
    points = [
        point
        for point in range(0x80, 0x110000)
        if not 0xD800 <= point <= 0xDFFF and chr(point).isdigit() and not chr(point).isdecimal()
    ]
    expected = ",".join(f"{a:x}" if b == a + 1 else f"{a:x}-{b - 1:x}" for a, b in runs(points))
    source = (CLOUDFLARE / "src/lib/digits.ts").read_text()
    declaration = source.split("DIGIT_ONLY_RANGES =", 1)[1].split(";", 1)[0]
    actual = "".join(re.findall(r'"([^"]*)"', declaration))
    if actual != expected:
        raise SystemExit(f"src/lib/digits.ts DIGIT_ONLY_RANGES differs from Python:\n{expected}\n{actual}")


def classes(name: str) -> list[tuple[int, int]]:
    return [_decode_range(r) for r in idnadata.codepoint_classes[name]]


def write_idna() -> None:
    allowed = sorted({cp for name in ("PVALID", "CONTEXTJ", "CONTEXTO") for a, b in classes(name) for cp in range(a, b)})
    # Bidirectional classes of the code points a label may hold, in runs ('' for those Python's unicodedata does
    # not know, which check_bidi refuses).
    names: list[str] = []
    bidi: list[tuple[int, int, int]] = []
    for cp in allowed:
        direction = unicodedata.bidirectional(chr(cp))
        if direction not in names:
            names.append(direction)
        index = names.index(direction)
        if bidi and bidi[-1][2] == index and bidi[-1][1] == cp:
            bidi[-1] = (bidi[-1][0], cp + 1, index)
        else:
            bidi.append((cp, cp + 1, index))
    joining = {kind: [_decode_range(r) for r in ranges] for kind, ranges in idnadata.joining_types.items()}
    # `_combining_class(cp) == 9`: a virama; a code point without a name raises, which valid_contextj reports.
    virama = [cp for cp in range(0x110000) if not 0xD800 <= cp <= 0xDFFF and unicodedata.combining(chr(cp)) == 9]
    unnamed = [cp for cp in allowed if unicodedata.combining(chr(cp)) == 0 and not unicodedata.name(chr(cp), "")]
    marks = [cp for cp in range(0x110000) if not 0xD800 <= cp <= 0xDFFF and unicodedata.category(chr(cp))[0] == "M"]
    starts = list(uts46_starts)
    statuses = bytes(uts46_statuses).decode("ascii")
    assert all(starts[i] == i for i in range(256))
    replacements = [uts46_replacements[i] or "" for i, status in enumerate(statuses) if status == "M"]
    lines = [
        f"// Generated by test/fixtures/connectors/google/generate.py from Python {VERSION} (unicodedata "
        f"{unicodedata.unidata_version}) and the idna package's tables {idnadata.__version__}. Do not edit.",
        "// Ranges are packed as base-36 gaps and lengths (idna.ts `unpack`).",
        "",
        f"export const PVALID = {json.dumps(packed(classes('PVALID')))};",
        f"export const CONTEXTJ = {json.dumps(packed(classes('CONTEXTJ')))};",
        f"export const CONTEXTO = {json.dumps(packed(classes('CONTEXTO')))};",
        "export const SCRIPTS: Readonly<Record<string, string>> = {",
        *(f"\t{name}: {json.dumps(packed([_decode_range(r) for r in ranges]))}," for name, ranges in sorted(idnadata.scripts.items())),
        "};",
        "export const JOINING: readonly (readonly [string, string])[] = [",
        *(f"\t[{json.dumps(kind)}, {json.dumps(packed(ranges))}]," for kind, ranges in joining.items()),
        "];",
        "/** Canonical combining class 9. */",
        f"export const VIRAMA = {json.dumps(packed(runs(virama)))};",
        "/** Code points a label may hold with combining class 0 and no name: `_combining_class` raises for these. */",
        f"export const UNNAMED = {json.dumps(packed(runs(unnamed)))};",
        "/** General category M. */",
        f"export const MARKS = {json.dumps(packed(runs(marks)))};",
        f"export const BIDI_NAMES: readonly string[] = {json.dumps(names)};",
        f"export const BIDI_RANGES = {json.dumps(packed([(a, b) for a, b, _ in bidi]))};",
        f"export const BIDI_CLASSES = {json.dumps(''.join(b36(i) for _, _, i in bidi))};",
        "/** UTS #46: the first code point of each run, as base-36 gaps from the previous run's start. */",
        f"export const UTS46_STARTS = {json.dumps(','.join(b36(s - p) for s, p in zip(starts, [0, *starts[:-1]], strict=True)))};",
        "/** Each run's status: V(alid), M(apped), D(eviation), I(gnored) or X (disallowed). */",
        f"export const UTS46_STATUSES = {json.dumps(statuses)};",
        "/** The replacement of each mapped run, in order. */",
        f"export const UTS46_REPLACEMENTS: readonly string[] = [{', '.join(js_string(r) for r in replacements)}];",
        "",
    ]
    (CLOUDFLARE / "src/lib/idna-table.ts").write_text("\n".join(lines))


SPECIAL_CODECS = {
    "ascii", "latin_1", "utf_8", "utf_8_sig", "utf_16", "utf_16_le", "utf_16_be", "utf_32", "utf_32_le", "utf_32_be",
    "utf_7", "unicode_escape", "raw_unicode_escape", "idna", "punycode", "undefined", "charmap",
    # Decoded from Python's own tables (src/lib/cjk-table.ts, written by test/fixtures/codecs/generate.py).
    "gb2312", "hz", "iso2022_kr", "johab",
}
# Decoded with the runtime's TextDecoder (the Encoding Standard's decoders), the nearest of which is named.
WHATWG = {
    "big5": "big5", "big5hkscs": "big5", "cp950": "big5", "cp932": "shift_jis", "shift_jis": "shift_jis",
    "shift_jis_2004": "shift_jis", "shift_jisx0213": "shift_jis", "euc_jp": "euc-jp", "euc_jis_2004": "euc-jp",
    "euc_jisx0213": "euc-jp", "euc_kr": "euc-kr", "cp949": "euc-kr", "gbk": "gbk",
    "gb18030": "gb18030", "iso2022_jp": "iso-2022-jp", "iso2022_jp_1": "iso-2022-jp", "iso2022_jp_2": "iso-2022-jp",
    "iso2022_jp_2004": "iso-2022-jp", "iso2022_jp_3": "iso-2022-jp", "iso2022_jp_ext": "iso-2022-jp",
}


def write_codecs() -> None:
    kinds: dict[str, str] = {}
    tables: dict[str, str] = {}
    for module in sorted(m.name for m in pkgutil.iter_modules(encodings.__path__)):
        if module.startswith("_"):
            continue
        try:
            info = codecs.lookup(module)
        except LookupError:
            # Imported, but not a codec module (aliases), or not on this platform (mbcs, oem).
            kinds[module] = "missing" if module in ("mbcs", "oem") else "module"
            continue
        if not info._is_text_encoding:
            kinds[module] = "binary"
        elif module in SPECIAL_CODECS:
            kinds[module] = module
        elif module in WHATWG:
            kinds[module] = "whatwg:" + WHATWG[module]
        else:
            table = []
            single = True
            for byte in range(256):
                try:
                    text = bytes([byte]).decode(module)
                except UnicodeDecodeError:
                    text = "￾"
                if len(text) != 1:
                    single = False
                table.append(text)
            if single and module not in ("hz", "iso2022_kr", "johab"):
                kinds[module] = "table"
                tables[module] = "".join(table)
            else:
                kinds[module] = "unsupported"
    ascii_low = "".join(chr(i) for i in range(128))
    lines = [
        HEADER.format(version=VERSION),
        "/** `encodings.aliases.aliases`: a normalized name to its codec module. */",
        "export const ALIASES: Readonly<Record<string, string>> = {",
        *(f"\t{js_string(k)}: {js_string(v)}," for k, v in sorted(encodings.aliases.aliases.items())),
        "};",
        "",
        "/**",
        " * The modules of the `encodings` package and how each decodes: `table` (a single-byte table below), the",
        " * module's own name for the codecs codecs.ts implements, `whatwg:<label>` for the runtime's TextDecoder,",
        " * `binary` for bytes-to-bytes codecs (not a text encoding), `missing` for modules this platform lacks",
        " * (an ImportError, so the next name is tried), `module` for one that is not a codec, and `unsupported`.",
        " */",
        "export const MODULES: Readonly<Record<string, string>> = {",
        *(f"\t{js_string(k)}: {js_string(v)}," for k, v in sorted(kinds.items())),
        "};",
        "",
        "/** Each single-byte codec's 256 characters, U+FFFE where a byte is undefined; `~` before 128 more means ASCII then those. */",
        "export const TABLES: Readonly<Record<string, string>> = {",
        *(f"\t{js_string(k)}: {js_string('~' + v[128:] if v[:128] == ascii_low else v)}," for k, v in sorted(tables.items())),
        "};",
        "",
    ]
    (CLOUDFLARE / "src/lib/codec-table.ts").write_text("\n".join(lines))


def main() -> None:
    write_zones()
    check_digits()
    write_idna()
    write_codecs()
    vectors = {
        "dates": date_times(),
        "calendar": calendar_inputs(),
        "drive": drive_inputs(),
        "base": base_cases(),
    }
    (HERE / "vectors.json").write_text(json.dumps(compact(vectors), sort_keys=True, ensure_ascii=True, separators=(",", ":")) + "\n")
    gmail = {
        "inputs": gmail_inputs(),
        "base64": base64_cases(),
        "codecs": codec_cases(),
        "headers": header_cases(),
        "content_type": content_type_cases(),
        "content": content_cases(),
        "address_headers": address_header_cases(),
        "threading": threading_cases(),
        "raw": raw_cases(),
        "html": html_cases(),
        "addresses": address_cases(),
        "idna": idna_cases(),
        "snippets": snippets(),
        # Drawn from RANDOM last, so that the groups above keep their cases when these change.
        "raw_random": random_raw_cases(),
        "headers_random": random_header_cases(),
    }
    (HERE / "gmail.json").write_text(json.dumps(compact(gmail), sort_keys=True, ensure_ascii=True, separators=(",", ":")) + "\n")


if __name__ == "__main__":
    main()
